package run.ikaros.password; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/password") public class PasswordFolderController{private final PasswordFolderService service;public PasswordFolderController(PasswordFolderService s){service=s;}@PostMapping("/vaults/{vaultId}/folders")public Mono<PasswordFolderView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID vaultId,@Valid@RequestBody CreatePasswordFolderRequest r){return service.create(a,vaultId,r);}@GetMapping("/vaults/{vaultId}/folders")public Flux<PasswordFolderView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID vaultId){return service.list(a,vaultId);}@PostMapping("/items/{itemId}/folder")public Mono<PasswordFolderView> bind(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID itemId,@Valid@RequestBody BindPasswordFolderRequest r){return service.bind(a,itemId,r);}}
